L["Version:"] = "Versión:"
L["What To Show"] = "Qué mostrar"
L["When disabled, the Minimap will not be modified by AzeriteUI. When enabled, the Minimap will use the selected theme and positioning."] = "Cuando está desactivado, AzeriteUI no modificará el minimapa. Cuando está activado, el minimapa usará el tema y posicionamiento seleccionados."
L["When enabled, the world map uses the integrated Rui-style clean border, shrink-on-maximize behavior, and player/cursor coordinates."] = "Cuando está activado, el mapa del mundo usa el borde limpio estilo Rui integrado, el comportamiento de reducción al maximizar y las coordenadas del jugador/cursor."
L["When enabled, unit-frame auras are grouped by relevance and readable timing when possible. When disabled, they stay closer to application order, like the default UI."] = "Cuando está activado, las auras del marco de unidad se agrupan por relevancia y temporización legible cuando es posible. Cuando está desactivado, se mantienen más cerca del orden de aplicación, como en la interfaz predeterminada."
L["When to start Explorer Mode"] = "Cuándo iniciar el Modo Explorador"
L["While having a dead target"] = "Al tener un objetivo muerto"
L["White"] = "Blanco"
L["Widget Visibility"] = "Visibilidad de elementos"
L["You can choose to have a delay before the Explorer Mode starts after loading screens."] = "Puedes elegir tener un retraso antes de que el Modo Explorador se inicie tras las pantallas de carga."
L["Below the bar"] = "Debajo de la barra"
L["Choose whether nameplate health text sits below the bar, inside the bar, or only moves inside while you are in combat."] = "Elige si el texto de salud de la placa de nombre se muestra debajo de la barra, dentro de la barra o solo dentro durante el combate."
L["Chooses theme for the Tooltips."] = "Elige el tema para los tooltips."
L["Health text placement"] = "Posición del texto de salud"
L["Inside in combat"] = "Dentro en combate"
L["Inside the bar"] = "Dentro de la barra"
L["Set Tooltip Theme (Experimental)"] = "Establecer tema de tooltip (Experimental)"
L["Show auras"] = "Mostrar auras"
L["Show current health percent next to player alternate health value text."] = "Mostrar el porcentaje de salud actual junto al texto de salud del jugador alternativo."
L["Show current health percent next to player health value text."] = "Mostrar el porcentaje de salud actual junto al texto de salud del jugador."
L["Show current target health percent next to target health value text."] = "Mostrar el porcentaje de salud actual del objetivo junto al texto de salud del objetivo."
L["Show Guildname"] = "Mostrar nombre de hermandad"
L["Show Health Percent"] = "Mostrar porcentaje de salud"
L["Toggle whether to add Guildname in tooltips or not."] = "Activar o desactivar la visualización del nombre de hermandad en los tooltips."
L["These settings control the Blizzard-managed Retail aura row attached to the player frame. Custom categories use only native Retail 12.1 filters that remain safe in combat; the main top-right aura header is unaffected."] = "Estos ajustes controlan la fila de auras de Retail gestionada por Blizzard y vinculada al marco del jugador. Las categorías personalizadas solo usan filtros nativos de Retail 12.1 seguros en combate; el encabezado principal de auras de la esquina superior derecha no se modifica."
L["Custom Buff Categories"] = "Categorías de mejoras personalizadas"
L["Show buffs from AzeriteUI's maintained priority spell list."] = "Mostrar mejoras de la lista de hechizos prioritarios mantenida por AzeriteUI."
L["Show buffs Blizzard marks as boss or role auras."] = "Mostrar mejoras que Blizzard marca como auras de jefe o de función."
L["Show helpful effects Blizzard marks as stealable."] = "Mostrar efectos beneficiosos que Blizzard marca como robables."
L["Stealable Buffs"] = "Mejoras robables"
L["Player / Self Buffs"] = "Mejoras del jugador / propias"
L["Show personal combat auras and remaining temporary buffs cast by you or your pet."] = "Mostrar auras de combate personales y las mejoras temporales restantes lanzadas por ti o tu mascota."
L["Nameplate-Highlighted Buffs"] = "Mejoras resaltadas en placas de nombre"
L["Show helpful effects Blizzard also marks for nameplate display."] = "Mostrar efectos beneficiosos que Blizzard también marca para mostrarlos en las placas de nombre."
L["Other Temporary Buffs"] = "Otras mejoras temporales"
L["Show remaining temporary buffs from other sources. This native duration filter stays consistent in and out of combat."] = "Mostrar las mejoras temporales restantes de otras fuentes. Este filtro nativo de duración se mantiene igual dentro y fuera de combate."
L["Maximum Temporary Duration"] = "Duración temporal máxima"
L["Set the maximum original duration for the remaining temporary-buff group."] = "Establecer la duración original máxima del grupo de mejoras temporales restantes."
L["Extend the temporary-buff group to include long-duration and permanent utility buffs. Usually leave this off so those remain in the main aura header only."] = "Ampliar el grupo de mejoras temporales para incluir mejoras de utilidad permanentes y de larga duración. Normalmente debe dejarse desactivado para que solo aparezcan en el encabezado principal de auras."
L["Show Debuffs"] = "Mostrar perjuicios"
L["Hide helpful effects from the attached player aura row and show only harmful effects on you."] = "Ocultar los efectos beneficiosos de la fila de auras vinculada al jugador y mostrar solo los efectos perjudiciales sobre ti."
L["Include harmful effects in the attached row when Show Debuffs Only and Separate Player Debuff Row are disabled."] = "Incluir efectos perjudiciales en la fila vinculada cuando Mostrar solo perjuicios y Fila de perjuicios del jugador separada estén desactivados."
L["Auras Shown"] = "Auras mostradas"
L["Set the maximum number of slots in the attached player aura row. When buffs and debuffs share the row, Retail-safe group budgets divide these slots between them; use the separate debuff row to devote every attached slot to buffs."] = "Establecer el número máximo de espacios en la fila de auras vinculada al jugador. Cuando las mejoras y los perjuicios comparten la fila, los límites de grupo seguros de Retail dividen estos espacios; usa la fila separada de perjuicios para dedicar todos los espacios vinculados a las mejoras."
L["Separate Player Debuff Row"] = "Fila separada de perjuicios del jugador"
L["Keep the normal player aura row attached to the frame. When enabled, harmful auras are filtered out of that row and shown in a separate movable debuff layer instead. When disabled, the debuff layer stays hidden but can still be positioned with /lock."] = "Mantener la fila normal de auras del jugador vinculada al marco. Al activarlo, las auras perjudiciales se filtran de esa fila y se muestran en una capa de perjuicios separada y movible. Al desactivarlo, la capa permanece oculta, pero puede colocarse con /lock."
L["Separate Debuffs Shown"] = "Perjuicios separados mostrados"
L["Set how many debuffs can appear on the separate player debuff row."] = "Establecer cuántos perjuicios pueden aparecer en la fila separada de perjuicios del jugador."

L["Micro Menu"] = "Micromenú"
L["Show AzeriteUI Cog Wheel"] = "Mostrar la rueda dentada de AzeriteUI"
L["Show the AzeriteUI cog wheel in the bottom right corner. Clicking it opens the micro menu."] = "Muestra la rueda dentada de AzeriteUI en la esquina inferior derecha. Al pulsarla se abre el micromenú."
L["Show Blizzard's Micro Menu"] = "Mostrar el micromenú de Blizzard"
L["Restore Blizzard's own micro menu along the bottom of the screen. This is independent of the cog wheel above, so you can use either or both."] = "Restaura el micromenú propio de Blizzard en la parte inferior de la pantalla. Es independiente de la rueda dentada anterior, así que puedes usar uno, otro o ambos."
L["Both settings apply when the interface loads, so changing either one will ask you to reload."] = "Ambos ajustes se aplican al cargar la interfaz, así que cambiar cualquiera de ellos te pedirá recargar."
L["The micro menu holds the buttons for your character sheet, spellbook, collections, group finder and the game menu. AzeriteUI replaces Blizzard's strip along the bottom of the screen with a cog wheel in the bottom right corner."] = "El micromenú contiene los botones de tu hoja de personaje, grimorio, colecciones, buscador de grupo y el menú del juego. AzeriteUI sustituye la barra de Blizzard en la parte inferior de la pantalla por una rueda dentada en la esquina inferior derecha."
L["The micro menu is built when the interface loads, so this change needs a reload to take effect."] = "El micromenú se crea al cargar la interfaz, así que este cambio necesita recargar para aplicarse."
L["Reload UI"] = "Recargar interfaz"
L["Show Specialization Icons"] = "Mostrar iconos de especialización"
L["Show each party member's specialization icon in place of their portrait. A member's specialization can only be read by inspecting them, so it stays a portrait until they are close enough and visible."] = "Muestra el icono de especialización de cada miembro del grupo en lugar de su retrato. La especialización solo puede leerse inspeccionando al jugador, así que se mantiene el retrato hasta que esté lo bastante cerca y visible."
L["Show each raid member's specialization icon in place of their portrait. A member's specialization can only be read by inspecting them, so it stays a portrait until they are close enough and visible."] = "Muestra el icono de especialización de cada miembro de la banda en lugar de su retrato. La especialización solo puede leerse inspeccionando al jugador, así que se mantiene el retrato hasta que esté lo bastante cerca y visible."
L["Show each raid member's specialization icon on the role badge beside their health bar, including damage dealers, who normally have no badge. A member's specialization can only be read by inspecting them, so it stays the plain role icon until they are close enough and visible."] = "Muestra el icono de especialización de cada miembro de la banda en la insignia de rol junto a su barra de salud, incluidos los infligidores de daño, que normalmente no tienen insignia. La especialización solo puede leerse inspeccionando al jugador, así que se mantiene el icono de rol normal hasta que esté lo bastante cerca y visible."

L["Show while mounted"] = "Mostrar mientras montas"
L["Keep this bar visible while you are mounted. Turn this off to hide it instead, which also stops you clicking its buttons by accident. Your skyriding bar is unaffected."] = "Mantiene esta barra visible mientras estás montado. Desactívalo para ocultarla en su lugar, lo que también evita que pulses sus botones por accidente. La barra de vuelo dracónico no se ve afectada."
L["Ignore clicks while faded"] = "Ignorar clics mientras está atenuada"
L["Stop faded out buttons from casting when you click them. Faded buttons are invisible but still live, so clicking where one sits will use it. With this on, the click is ignored until you hover the bar and the buttons come back into view."] = "Evita que los botones atenuados se lancen al pulsarlos. Los botones atenuados son invisibles pero siguen activos, así que pulsar donde está uno lo usa. Con esto activado, el clic se ignora hasta que pasas el ratón por la barra y los botones vuelven a aparecer."

L["<Left-Click> an anchor to select it and raise it."] = "<Clic izquierdo> en un anclaje para seleccionarlo y traerlo al frente."
L["<Right-Click> an anchor to deselect it and/or lower it."] = "<Clic derecho> en un anclaje para deseleccionarlo o enviarlo atrás."
L["Choose stock AzeriteUI power colors, enhanced token-based power colors, or your class color."] = "Elige los colores de poder estándar de AzeriteUI, los colores de poder mejorados basados en tokens o el color de tu clase."
L["Fine-tune the position."] = "Ajusta la posición con precisión."
L["Help"] = "Ayuda"
L["ID"] = "ID"
L["Only numbers are allowed."] = "Solo se permiten números."
L["Vehicle Seat"] = "Asiento del vehículo"
L["Widgets: Minimap"] = "Widgets: Minimapa"
L["Widgets: Top"] = "Widgets: Arriba"

L["How many seconds to wait after logging in before Explorer Mode starts fading anything. Set to 0 to start immediately."] = "Cuántos segundos esperar tras iniciar sesión antes de que el Modo explorador empiece a atenuar algo. Ponlo a 0 para empezar de inmediato."
L["How many seconds to wait after a user interface reload before Explorer Mode starts fading anything. Set to 0 to start immediately."] = "Cuántos segundos esperar tras recargar la interfaz antes de que el Modo explorador empiece a atenuar algo. Ponlo a 0 para empezar de inmediato."
L["How many seconds to wait after any other loading screen before Explorer Mode starts fading anything. Set to 0 to start immediately."] = "Cuántos segundos esperar tras cualquier otra pantalla de carga antes de que el Modo explorador empiece a atenuar algo. Ponlo a 0 para empezar de inmediato."
L["How many seconds to wait after leaving combat before Explorer Mode fades your interface out again. Set to 0 to fade immediately."] = "Cuántos segundos esperar tras salir de combate antes de que el Modo explorador vuelva a atenuar tu interfaz. Ponlo a 0 para atenuar de inmediato."
L["Keep your interface visible while you are in combat."] = "Mantiene tu interfaz visible mientras estés en combate."
L["Keep your interface visible while your health is below the threshold set below."] = "Mantiene tu interfaz visible mientras tu salud esté por debajo del umbral definido abajo."
L["Keep your interface visible while your mana is below the threshold set below."] = "Mantiene tu interfaz visible mientras tu maná esté por debajo del umbral definido abajo."
L["Keep your interface visible while you are in a party or raid."] = "Mantiene tu interfaz visible mientras estés en un grupo o banda."
L["Keep your interface visible while you are inside a dungeon, raid or battleground."] = "Mantiene tu interfaz visible mientras estés dentro de una mazmorra, banda o campo de batalla."
L["Keep your interface visible while you have a friendly target selected."] = "Mantiene tu interfaz visible mientras tengas seleccionado un objetivo aliado."
L["Keep your interface visible while you have a hostile target selected."] = "Mantiene tu interfaz visible mientras tengas seleccionado un objetivo hostil."
L["Keep your interface visible while you have a dead target selected. Unavailable while both friendly and hostile targets already keep it visible."] = "Mantiene tu interfaz visible mientras tengas seleccionado un objetivo muerto. No disponible mientras los objetivos aliados y hostiles ya la mantengan visible."
L["Keep your interface visible while you have a focus target set."] = "Mantiene tu interfaz visible mientras tengas fijado un objetivo de foco."
L["Include your action bars in what Explorer Mode fades out."] = "Incluye tus barras de acción en lo que atena el Modo explorador."
L["Include your pet bar in what Explorer Mode fades out."] = "Incluye tu barra de mascota en lo que atena el Modo explorador."
L["Include your stance bar in what Explorer Mode fades out."] = "Incluye tu barra de posturas en lo que atena el Modo explorador."
L["Include your player unit frame in what Explorer Mode fades out."] = "Incluye tu marco de jugador en lo que atena el Modo explorador."
L["Include your class power display, such as combo points or runes, in what Explorer Mode fades out."] = "Incluye tu indicador de poder de clase, como puntos de combo o runas en lo que atena el Modo explorador."
L["Include your pet unit frame in what Explorer Mode fades out."] = "Incluye tu marco de mascota en lo que atena el Modo explorador."
L["Include your focus unit frame in what Explorer Mode fades out."] = "Incluye tu marco de foco en lo que atena el Modo explorador."
L["Include the objectives tracker in what Explorer Mode fades out."] = "Incluye el rastreador de objetivos en lo que atena el Modo explorador."
L["Include your chat windows in what Explorer Mode fades out."] = "Incluye tus ventanas de chat en lo que atena el Modo explorador."

L["AzeriteUI hid Blizzard's group frames earlier this session and cannot bring them back on the fly."] = "AzeriteUI ocultó los marcos de grupo de Blizzard antes en esta sesión y no puede recuperarlos sobre la marcha."
L["Reload the interface to get them working again."] = "Recarga la interfaz para que vuelvan a funcionar."
